@Test
public void testExecTupleWithMultipleParentNodes() throws Exception {
    final XPathAll xpath = new XPathAll();
    final Tuple tuple = mock(Tuple.class);
    when(tuple.get(0)).thenReturn("<bookstore>" + "<book id=\"bk101\">" + "<authors>" + "<author_1>Gambardella</author_1>" + "<author_2>Matthew</author_2>" + "<author_3>Mike</author_3>" + "</authors>" + "<title>XML Developer's Guide</title>" + "<genre>Computer</genre>" + "<price>44.95</price>" + "<publish_date>2000-10-01</publish_date>" + "<description>An in-depth look at creating applications with XML.</description>" + "</book>" + "<book id=\"bk102\">" + "<authors>" + "<author_1>Kent</author_1>" + "<author_2>Beck</author_2>" + "</authors>" + "<title>HTML Developer's</title>" + "<genre>Computer</genre>" + "<price>60.00</price>" + "<publish_date>2000-10-01</publish_date>" + "<description>An in-depth look at creating applications with HTML.</description>" + "</book>" + "</bookstore>");
    when(tuple.size()).thenReturn(4);
    when(tuple.get(2)).thenReturn(true);
    when(tuple.get(3)).thenReturn(true);
    when(tuple.get(1)).thenReturn("bookstore/book");
    assertEquals(2, xpath.exec(tuple).getAll().size());
    assertEquals(", XML Developer's Guide, Computer, 44.95, 2000-10-01, An in-depth look at creating applications with XML.", xpath.exec(tuple).get(0));
    assertEquals(", HTML Developer's, Computer, 60.00, 2000-10-01, An in-depth look at creating applications with HTML.", xpath.exec(tuple).get(1));
    when(tuple.get(1)).thenReturn("bookstore/book/authors");
    assertEquals(2, xpath.exec(tuple).getAll().size());
    assertEquals("Gambardella, Matthew, Mike", xpath.exec(tuple).get(0));
    assertEquals("Kent, Beck", xpath.exec(tuple).get(1));
}

